const NEWI={rocket:'<path d="M5 15c-1.5 1.5-2 5-2 5s3.5-.5 5-2"/><path d="M14 4c3-1 6-1 6-1s0 3-1 6l-7 7-5-5z"/><circle cx="15" cy="9" r="1.5"/>',flame:'<path d="M12 3c1 4 5 5 5 10a5 5 0 0 1-10 0c0-2 1-3 2-4 0 2 1 3 2 3 0-4 0-6 1-9z"/>',crown:'<path d="M3 8l4 4 5-7 5 7 4-4-2 11H5z"/>',lock:'<rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/>',sparkle:'<path d="M12 3l2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18c1.5 0 2-1 1.5-2s0-2 1.5-2h2a3 3 0 0 0 3-3c0-5-4-11-8-11z"/><circle cx="8" cy="10" r="1"/><circle cx="12" cy="7" r="1"/><circle cx="16" cy="10" r="1"/>'};
Object.entries(NEWI).forEach(([k,p])=>addI(k,p));
const ICONMAP=[[/like|suka|promo|iklan|boost|naik/,'rocket'],[/centang|biru|verif|badge|lencana/,'check'],[/reel|film|video|sinema|live|siaran|kamera|stream/,'film'],[/musik|lagu|artis|audio|spotify|playlist/,'music'],[/mic|suara|podcast|karaoke/,'mic'],[/game|main|match|kuis|quiz|wordle/,'game'],[/chat|pesan|dm|grup|group|family/,'send'],[/komentar|ulasan|review/,'comment'],[/toko|belanja|jual|affiliate|lapak|shop/,'store'],[/hadiah|gift|kado|mawar|bunga|coin|koin/,'gift'],[/streak|api|fire|flame/,'flame'],[/crown|raja|ratu|king|queen/,'crown'],[/eksklusif|exclusive|vip|premium|member|bintang|star/,'star'],[/rumah|home|beranda/,'home'],[/saldo|bank|uang|top ?up|dompet|saham|aset|invest|emas/,'bag'],[/tema|warna|theme|color/,'palette'],[/kunci|lock|privat|rahasia/,'lock'],[/pengguna|user|akun|profil/,'user'],[/notif|alert/,'bell'],[/cari|search|jelajah/,'search']];
const autoIcon=t=>{t=String(t||'').toLowerCase();for(const [re,k] of ICONMAP)if(re.test(t)&&I[k])return k;return I.sparkle?'sparkle':'gift'};
const dayNum=()=>{const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5)};

/* harga & promo */
async function loadPricing(force){if(S.pricing&&!force)return S.pricing;let d={};try{const s=await getDoc(doc(db,'config','pricing'));if(s.exists())d=s.data()}catch{}S.pricing={likePrice:d.likePrice||20000,likePack:d.likePack||1000,exclMin:d.exclMin??1000};return S.pricing}
async function loadPromos(){if(S.promo&&Date.now()-(S.promoT||0)<60000)return;S.promoT=Date.now();const m={};try{(await getDocs(query(collection(db,'promos'),where('active','==',true),limit(60)))).docs.forEach(d=>m[d.id]=d.data())}catch{}S.promo=m}
const promoLive=p=>{const x=S.promo&&S.promo[p.id];return x&&((p.likeCount||0)-(x.startLikes||0))<(x.target||0)?x:null};
function wrapBody(p,html){let pre='';if(promoLive(p))pre+=`<div class="promol">${I.rocket} Dipromosikan</div>`;
if(p.excl){const ok=p.uid==S.uid||S.isAdmin||S.following.has(p.uid);if(!ok)return pre+`<div class="exl"><span class="ic">${I.lock}</span><b>Konten eksklusif</b><p>Ikuti @${esc(S.users[p.uid]?.username||'')} untuk melihat konten ini.</p><button class="btn sm" data-act="exfollow" data-id="${p.uid}">Ikuti</button></div>`;pre+=`<div class="promol exb">${I.crown} Eksklusif</div>`}return pre+html}
A.exfollow=async e=>{const id=e.dataset.id,c=e.closest('.card[data-pid]');await ACT.follow(e);if(S.following.has(id)&&c){const p=S.pc[c.dataset.pid]||(S.raw||[]).find(x=>x.id==c.dataset.pid);if(p){const t=document.createElement('div');t.innerHTML=card(p);c.replaceWith(t.firstElementChild);}}};
async function exclUI(sh){const el=$('#c_ex',sh);if(!el)return;await loadPricing();let ok=!!S.me.verified;if(!ok){try{const c=await getCountFromServer(query(collection(db,'follows'),where('followee','==',S.uid)));ok=c.data().count>=S.pricing.exclMin}catch{}}
el.innerHTML=ok?`<label class="row" style="gap:8px;margin-top:10px;align-items:center"><input id="c_exv" type="checkbox" style="width:auto"> <span class="ic" style="width:18px">${I.crown}</span> Konten eksklusif (hanya pengikut yang bisa melihat)</label>`:`<p class="mut" style="font-size:12px;margin:10px 0 0">Konten eksklusif tersedia untuk akun Centang Biru atau yang punya ${S.pricing.exclMin} pengikut.</p>`}
A.promo=async e=>{const pid=e.dataset.id,p=S.pc[pid]||(S.raw||[]).find(x=>x.id==pid);if(!p)return;const P=await loadPricing();await loadPromos();const act=promoLive(p);
if(act)return toast('Postingan ini sedang dipromosikan: '+Math.max(0,(act.target||0)-((p.likeCount||0)-(act.startLikes||0)))+' like lagi menuju target');
S.pm={pid,packs:1};sheet(`<h3>${ic('rocket')} Promosikan postingan</h3><p class="mut">Postinganmu tampil lebih sering di beranda pengguna lain sampai mendapat tambahan like sesuai paket.</p><div class="seg" id="pm_s">${[1,2,3,5].map(n=>`<button class="${n==1?'on':''}" data-act="pmset" data-n="${n}">${n*P.likePack} like</button>`).join('')}</div><div class="card pad" style="margin:10px 0"><div class="row"><span class="sp">Total bayar</span><b id="pm_t">${nv(P.likePrice)}</b></div><div class="row"><span class="sp mut">Saldo kamu</span><span>${nv(S.me.balance)}</span></div></div><button class="btn block" data-act="pmbuy">Bayar dan mulai promosi</button><p class="mut" style="font-size:12px">Harga ${nv(P.likePrice)} per ${P.likePack} like. Dibayar dari saldo RVNBANK.</p>`)};
A.pmset=e=>{const n=+e.dataset.n,P=S.pricing;S.pm.packs=n;$$('#pm_s button').forEach(b=>b.classList.toggle('on',b==e));$('#pm_t').textContent=nv(P.likePrice*n)};
A.pmbuy=async e=>{const {pid,packs}=S.pm||{};const P=await loadPricing(),p=S.pc[pid]||(S.raw||[]).find(x=>x.id==pid);if(!p)return;const cost=P.likePrice*packs;if((S.me.balance||0)<cost)return toast('Saldo tidak cukup. Top up dulu di RVNBANK.');e.disabled=true;
const tid=doc(collection(db,'transfers')).id,ur=doc(db,'users',S.uid),or=doc(db,'users',OFFICIAL_UID);
try{await runTransaction(db,async tx=>{const [m,o]=await Promise.all([tx.get(ur),tx.get(or)]);if(!o.exists())throw Error('Sistem belum siap. Hubungi admin.');const mb=m.data().balance||0;if(mb<cost)throw Error('Saldo tidak cukup.');
tx.set(doc(db,'transfers',tid),{from:S.uid,to:OFFICIAL_UID,amount:cost,note:'Promosi '+packs*P.likePack+' like',createdAt:serverTimestamp()});
tx.update(ur,{balance:mb-cost,lastTx:tid,spent:(m.data().spent||0)+cost});tx.update(or,{balance:(o.data().balance||0)+cost,lastTx:tid});
tx.set(doc(db,'promos',pid),{uid:S.uid,pid,packs,target:packs*P.likePack,startLikes:p.likeCount||0,price:cost,tid,active:true,at:serverTimestamp()})});
S.me.balance=(S.me.balance||0)-cost;S.promoT=0;await loadPromos();closeSheet();toast('Promosi dimulai');if(S.view=='home')X.refreshFeed?.()}catch(x){toast(errMsg(x));e.disabled=false}};

/* bagikan */
const PC={},SM={};
async function postMini(pid){if(PC[pid]!==undefined)return PC[pid];try{const d=await getDoc(doc(db,'posts',pid));PC[pid]=d.exists()?{id:d.id,...d.data()}:null}catch{PC[pid]=null}if(PC[pid]){await getUser(PC[pid].uid);S.pc[pid]=S.pc[pid]||PC[pid]}return PC[pid]}
async function storyMini(sid){if(SM[sid]!==undefined)return SM[sid];try{const d=await getDoc(doc(db,'stories',sid));SM[sid]=d.exists()?{id:d.id,...d.data()}:null}catch{SM[sid]=null}return SM[sid]}
function thumbOf(p){const im=(p.images||[])[0];if(im)return`<img src="${esc(im)}" alt="">`;const po=poster(p.video);if(po)return`<img src="${esc(po)}" alt="">`;return`<div class="thx">${p.video?I.film:esc((p.text||'').slice(0,40))}</div>`}
async function fillShp(root){for(const el of $$('.shp[data-ref]:not([data-ok])',root)){el.dataset.ok=1;const p=await postMini(el.dataset.ref),b=$('.shpb',el);if(!b)continue;b.innerHTML=p?`<div class="shpt">${thumbOf(p)}</div><div class="shpx"><b>@${esc(S.users[p.uid]?.username||'')}</b><div>${esc(mask((p.text||(p.video?'Reels':'Foto')).slice(0,70)))}</div></div>`:'<span class="mut">Postingan sudah dihapus</span>'}}
const pUrl=pid=>location.origin+location.pathname+'#post='+pid;
A.share=async e=>{const pid=e.dataset.id;const rows=S.chats.filter(c=>c.lastAt||c.isGroup).sort((a,b)=>ms(b.lastAt||b.createdAt)-ms(a.lastAt||a.createdAt)).slice(0,30);await Promise.all(rows.flatMap(c=>c.isGroup?[]:[getUser(chatOther(c))]));
sheet(`<h3>Bagikan</h3><div class="row" style="gap:8px;margin-bottom:12px;flex-wrap:wrap"><button class="btn sm" data-act="shstory" data-id="${pid}">${ic('film')} Ke cerita</button><button class="btn sm soft" data-act="shcopy" data-id="${pid}">Salin tautan</button><button class="btn sm soft" data-act="shnative" data-id="${pid}">Aplikasi lain</button></div><div class="un" style="margin:4px 0 6px">Kirim ke teman atau grup</div><div id="shl" style="max-height:46vh;overflow:auto">${rows.length?rows.map(c=>{const g=c.isGroup,u=g?null:S.users[chatOther(c)]||{},a=g?(c.photo?`<img class="av" src="${esc(c.photo)}" alt="">`:`<div class="av">${esc((c.name||'G')[0].toUpperCase())}</div>`):av(u);return`<div class="chat-item">${a}<div class="sp">${g?`<span class="nm">${esc(c.name)}</span> <span class="pill b">${c.kind=='family'?'Family':'Grup'}</span>`:nameOf(u)}</div><button class="btn sm" data-act="shsend" data-pid="${pid}" data-cid="${c.id}">Kirim</button></div>`}).join(''):'<p class="mut c">Belum ada percakapan. Mulai chat dulu dengan temanmu.</p>'}</div>`)};
A.shsend=async e=>{const {pid,cid}=e.dataset;e.disabled=true;try{const b=writeBatch(db);b.set(doc(collection(db,'chats',cid,'messages')),{from:S.uid,text:'',img:'',kind:'post',ref:pid,createdAt:serverTimestamp()});b.update(doc(db,'chats',cid),{last:'Membagikan postingan',lastAt:serverTimestamp(),lastFrom:S.uid});await b.commit();e.textContent='Terkirim'}catch(x){toast(errMsg(x));e.disabled=false}};
A.shcopy=async e=>{try{await navigator.clipboard.writeText(pUrl(e.dataset.id));toast('Tautan disalin')}catch{toast('Tidak bisa menyalin')}};
A.shnative=async e=>{try{if(navigator.share)await navigator.share({title:'RVNOISE',text:'Lihat postingan ini di RVNOISE',url:pUrl(e.dataset.id)});else A.shcopy(e)}catch{}};
function wrapText(g,t,x,y,w,lh,max){let line='',n=0;for(const w1 of t.split(/\s+/)){const test=line?line+' '+w1:w1;if(g.measureText(test).width>w&&line){g.fillText(line,x,y);y+=lh;line=w1;if(++n>=max)return}else line=test}g.fillText(line,x,y)}
function postImage(p){const im=(p.images||[])[0];if(im)return im;const c=document.createElement('canvas');c.width=720;c.height=900;const g=c.getContext('2d'),gr=g.createLinearGradient(0,0,720,900);gr.addColorStop(0,'#ffd1e3');gr.addColorStop(1,'#bfdcff');g.fillStyle=gr;g.fillRect(0,0,720,900);g.fillStyle='#2b4a86';g.font='700 34px Poppins,Arial,sans-serif';g.fillText('RVNOISE',48,80);g.font='600 30px Poppins,Arial,sans-serif';g.fillStyle='#e0558c';g.fillText('@'+(S.users[p.uid]?.username||''),48,150);g.fillStyle='#23305a';g.font='500 44px Poppins,Arial,sans-serif';wrapText(g,(p.text||(p.video?'Lihat reels ini di RVNOISE':'')).slice(0,220),48,260,624,60,9);if(p.video){g.font='700 40px Poppins,Arial,sans-serif';g.fillStyle='#e0558c';g.fillText('RVNREELS',48,820)}return c.toDataURL('image/jpeg',.82)}
A.shstory=async e=>{const p=await postMini(e.dataset.id);if(!p)return toast('Postingan tidak ditemukan');e.disabled=true;try{await setDoc(doc(collection(db,'stories')),{uid:S.uid,image:postImage(p),text:('dari @'+(S.users[p.uid]?.username||'')).slice(0,120),createdAt:serverTimestamp()});closeSheet();toast('Dibagikan ke ceritamu')}catch(x){toast(errMsg(x));e.disabled=false}};

/* halaman satu postingan (dari notifikasi, chat, tautan) */
views.post=async function(arg){const [pid,fl]=String(arg||'').split(':'),t=S.tok;$('#main').innerHTML=`${back('home')}Postingan</h3></div><div id="pp">${SK}</div>`;const p=await postMini(pid);if(t!==S.tok)return;
if(!p){$('#pp').innerHTML='<p class="mut c pad">Postingan sudah dihapus.</p>';return}
if(p.repostOf){const o=await postMini(p.repostOf);if(o)S.pc[o.id]=o}S.pc[p.id]=p;try{S.liked[p.id]=(await getDoc(doc(db,'posts',p.id,'likes',S.uid))).exists()}catch{}
$('#pp').innerHTML=card(p);hydrate($('#pp'));if(fl=='c')setTimeout(()=>ACT.cmt({dataset:{id:p.id}}),250)};
