const modeOf=()=>lsg('rvn_mode')||'light',bgOf=()=>{const c=lsg('rvn_bg');return /^#[0-9a-f]{6}$/i.test(c||'')?c:''};
function applyMode(){const m=modeOf(),d=m=='dark'||(m=='auto'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.mode=d?'dark':'light';try{document.querySelector('meta[name=theme-color]')?.setAttribute('content',d?'#10131f':'#f6f9ff')}catch{}}
function applyBg(){const r=document.documentElement.style,c=bgOf();if(!c){['--bgc'].forEach(k=>r.removeProperty(k));return}const [R,G,B]=[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)),mx=w=>`rgb(${[R,G,B].map(v=>Math.round(v*(1-w)+255*w)).join(',')})`;r.setProperty('--pink',mx(.5));r.setProperty('--sky',mx(.78));r.setProperty('--blue',mx(.9));r.setProperty('--bgc',mx(.94))}
applyMode();applyBg();try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyMode)}catch{}
