const privLock=p=>{const au=S.users[p.uid];return au?.privacy?.priv&&p.uid!=S.uid&&!S.isAdmin&&p.uid!=OFFICIAL_UID&&!S.following.has(p.uid)?au:null};

/* ---------- suntik like: like langsung masuk ke postingan ---------- */
A.promo=async e=>{const pid=e.dataset.id,p=S.pc[pid]||(S.raw||[]).find(x=>x.id==pid);if(!p)return;const P=await loadPricing();S.pm={pid,packs:1};
sheet(`<h3>${ic('rocket')} Suntik like</h3><p class="mut">Like langsung bertambah di postinganmu setelah pembayaran.</p><div class="seg" id="pm_s">${[1,2,3,5,10].map(n=>`<button class="${n==1?'on':''}" data-act="pmset" data-n="${n}">+${n*P.likePack}</button>`).join('')}</div><div class="card pad" style="margin:10px 0"><div class="row"><span class="sp">Total bayar</span><b id="pm_t">${nv(P.likePrice)}</b></div><div class="row"><span class="sp mut">Saldo kamu</span><span>${nv(S.me.balance)}</span></div></div><button class="btn block" data-act="pmbuy">Beli sekarang</button><p class="mut" style="font-size:12px">Harga ${nv(P.likePrice)} per ${P.likePack} like. Dibayar dari saldo RVNBANK.</p>`)};
A.pmbuy=async e=>{const {pid,packs}=S.pm||{};const P=await loadPricing(),p=S.pc[pid]||(S.raw||[]).find(x=>x.id==pid);if(!p)return;const cost=P.likePrice*packs,add=packs*P.likePack;if((S.me.balance||0)<cost)return toast('Saldo tidak cukup. Top up dulu di RVNBANK.');e.disabled=true;
const tid=doc(collection(db,'transfers')).id,ur=doc(db,'users',S.uid),or=doc(db,'users',OFFICIAL_UID),pr=doc(db,'posts',pid);
try{let nb=0;await runTransaction(db,async tx=>{const [m,o,ps]=await Promise.all([tx.get(ur),tx.get(or),tx.get(pr)]);if(!o.exists())throw Error('Sistem belum siap. Hubungi admin.');if(!ps.exists())throw Error('Postingan tidak ditemukan');const mb=m.data().balance||0;if(mb<cost)throw Error('Saldo tidak cukup.');nb=(ps.data().boost||0)+add;
tx.set(doc(db,'transfers',tid),{from:S.uid,to:OFFICIAL_UID,amount:cost,note:'Suntik like +'+add,createdAt:serverTimestamp()});
tx.update(ur,{balance:mb-cost,lastTx:tid,spent:(m.data().spent||0)+cost});tx.update(or,{balance:(o.data().balance||0)+cost,lastTx:tid});tx.update(pr,{boost:nb,bTx:tid})});
S.me.balance=(S.me.balance||0)-cost;p.boost=nb;const q=(S.raw||[]).find(x=>x.id==pid);if(q)q.boost=nb;$$(`.lk[data-id="${pid}"] span`).forEach(s=>s.textContent=(p.likeCount||0)+nb);closeSheet();toast('+'+add+' like masuk')}catch(x){toast(errMsg(x));e.disabled=false}};

