/* ---------- PESAN SUARA ---------- */
const fmtT=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
let REC=null;
function drawRec(on){const c=$('.compose');if(!c)return;$('.vnbar',c)?.remove();if(on)c.insertAdjacentHTML('beforeend',`<div class="vnbar"><span class="rdot"></span><b id="vn_t">0:00</b><span class="sp mut">Merekam…</span><button class="ib" data-act="vncancel" aria-label="Batal">&times;</button><button class="btn sm" data-act="vnsend">Kirim</button></div>`)}
A.vnrec=async()=>{if(REC)return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder=='undefined')return toast('Perekaman suara belum didukung di perangkat ini');
try{const st=await navigator.mediaDevices.getUserMedia({audio:true});const mt=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t))||'';const mr=new MediaRecorder(st,{...(mt?{mimeType:mt}:{}),audioBitsPerSecond:20000});const R={mr,st,ch:[],t0:Date.now(),cancel:false};REC=R;
mr.ondataavailable=ev=>{if(ev.data&&ev.data.size)R.ch.push(ev.data)};
mr.onstop=async()=>{st.getTracks().forEach(t=>t.stop());clearInterval(R.tm);REC=null;drawRec(false);if(R.cancel)return;const dur=Math.max(1,Math.round((Date.now()-R.t0)/1000));if(Date.now()-R.t0<800)return toast('Terlalu singkat');const blob=new Blob(R.ch,{type:mr.mimeType||'audio/webm'});if(blob.size>520*1024)return toast('Pesan suara terlalu panjang');
const url=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(blob)});sendAny({kind:'vn',aud:url,dur})};
mr.start();R.tm=setInterval(()=>{const s=Math.round((Date.now()-R.t0)/1000);const el=$('#vn_t');if(el)el.textContent=fmtT(s);if(s>=60)A.vnsend()},400);drawRec(true)}catch{toast('Izin mikrofon dibutuhkan untuk pesan suara')}};
A.vnsend=()=>{if(REC&&REC.mr.state=='recording')REC.mr.stop()};
A.vncancel=()=>{if(REC){REC.cancel=true;if(REC.mr.state=='recording')REC.mr.stop()}};
const BARS=[5,9,14,8,16,11,6,13,17,10,7,15,9,12,6,10,14,8,5,9];
const vnHtml=(x,me,sn)=>`<div class="bub vnb ${me?'me':'th'}">${sn}<audio class="vna" preload="none" src="${esc(x.aud)}"></audio><button class="vnp" data-act="vnplay" aria-label="Putar">${I.play}</button><div class="vnw">${BARS.map(h=>`<i style="height:${h}px"></i>`).join('')}<span class="vnf"></span></div><span class="vnd">${fmtT(x.dur||0)}</span><span class="tm">${hm(x.createdAt)}</span></div>`;
A.vnplay=e=>{const b=e.closest('.vnb'),a=$('.vna',b);if(!a)return;document.querySelectorAll('.vna').forEach(o=>{if(o!==a){o.pause()}});if(a.paused){a.play().catch(()=>toast('Tidak bisa memutar'));}else a.pause()};
document.addEventListener('play',ev=>{const b=ev.target.closest?.('.vnb');if(b)$('.vnp',b).innerHTML=I.pause},true);
document.addEventListener('pause',ev=>{const b=ev.target.closest?.('.vnb');if(b)$('.vnp',b).innerHTML=I.play},true);
document.addEventListener('ended',ev=>{const b=ev.target.closest?.('.vnb');if(b){$('.vnp',b).innerHTML=I.play;$('.vnf',b).style.width='0'}},true);
document.addEventListener('timeupdate',ev=>{const a=ev.target,b=a.closest?.('.vnb');if(b&&a.duration)$('.vnf',b).style.width=Math.min(100,a.currentTime/a.duration*100)+'%'},true);

