ms.style.background=p.bgImg?`url(${p.bgImg}) center/cover`:p.bg||'';ms.style.borderRadius=(p.bgImg||p.bg)?'18px':'';ms.style.minHeight='55vh';ms.style.padding=(p.bgImg||p.bg)?'10px 8px':'';
if(p.bubble)ms.style.setProperty('--bm',p.bubble);else ms.style.removeProperty('--bm');ms.classList.toggle('cbub',!!p.bubble);
