async function gLeave(host,quiet){if(!S.gpc&&!S.gst)return;try{S.gpc?.close()}catch{}S.gst?.getTracks().forEach(t=>t.stop());(S.gun||[]).forEach(f=>f());S.gun=[];S.gpc=null;S.gst=null;S.gpcOk=0;await deleteDoc(doc(db,'lives',host,'grtc',S.uid)).catch(()=>{});await deleteDoc(doc(db,'lives',host,'guests',S.uid)).catch(()=>{});const v=$('#lv');if(v)v.muted=false;const el=$('#lgst');if(el)el.innerHTML='';if(!quiet)toast('Kamu keluar dari sesi bareng')}
function swapOut(stream){Object.values(S.livePcs||{}).forEach(pc=>pc.getSenders().forEach(s=>{if(!s.track)return;const t=stream.getTracks().find(x=>x.kind==s.track.kind);t&&s.replaceTrack(t).catch(()=>{})}))}
function gCompose(){if(!S.gstream||!S.live||S.gcv)return;const W=640,H=360,cv=document.createElement('canvas');cv.width=W;cv.height=H;const cx=cv.getContext('2d');
const mk=st=>{const v=document.createElement('video');v.muted=true;v.playsInline=true;v.autoplay=true;v.srcObject=st;v.play().catch(()=>{});return v},hv=mk(S.live),gv=mk(S.gstream);
const draw=()=>{cx.fillStyle='#000';cx.fillRect(0,0,W,H);[hv,gv].forEach((v,i)=>{const vw=v.videoWidth||320,vh=v.videoHeight||360,sw=W/2,sh=H,s=Math.max(sw/vw,sh/vh),dw=vw*s,dh=vh*s;cx.save();cx.beginPath();cx.rect(i*sw,0,sw,sh);cx.clip();cx.drawImage(v,i*sw+(sw-dw)/2,(sh-dh)/2,dw,dh);cx.restore()})};
S.gtm=setInterval(draw,40);draw();let ac=null,dest=null;try{const AC=window.AudioContext||window.webkitAudioContext;ac=new AC();dest=ac.createMediaStreamDestination();
if(S.live.getAudioTracks().length)ac.createMediaStreamSource(new MediaStream(S.live.getAudioTracks())).connect(dest);if(S.gstream.getAudioTracks().length)ac.createMediaStreamSource(new MediaStream(S.gstream.getAudioTracks())).connect(dest)}catch{}
const out=new MediaStream([...cv.captureStream(25).getVideoTracks(),...(dest?dest.stream.getAudioTracks():S.live.getAudioTracks())]);S.gcv={cv,ac};S.liveOut=out;swapOut(out);const lv=$('#lv');if(lv)lv.srcObject=out;toast('Live bareng dimulai')}
function gStop(){clearInterval(S.gtm);try{S.gcv?.ac?.close()}catch{}const had=!!S.gcv;S.gcv=null;S.gstream=null;S.gcur=null;S.liveOut=null;if(had&&S.live){swapOut(S.live);const v=$('#lv');if(v)v.srcObject=S.live;toast('Sesi bareng selesai')}}
/* ===== Panggilan suara & video ===== */
let CALL=null,RING=null;
const ringStart=(out)=>{try{const AC=window.AudioContext||window.webkitAudioContext,ac=new AC(),beep=()=>{const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=out?425:880;g.gain.value=.06;o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+(out?1:.35))};beep();RING={ac,t:setInterval(beep,out?3000:1200)}}catch{}};
const ringStop=()=>{if(RING){clearInterval(RING.t);try{RING.ac.close()}catch{}RING=null}};
function callUI(html){let o=$('#callov');if(!o){o=document.createElement('div');o.id='callov';document.body.appendChild(o)}o.innerHTML=html}
function callClose(){$('#callov')?.remove();ringStop()}
async function callMedia(video){return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:video?{facingMode:'user'}:false})}
function callPC(cid,role,st,video){const pc=new RTCPeerConnection(ICE),rs=new MediaStream();st.getTracks().forEach(t=>pc.addTrack(t,st));pc.ontrack=e=>{e.streams[0].getTracks().forEach(t=>rs.addTrack(t));const v=$('#cl_rv');if(v){v.srcObject=rs;v.play().catch(()=>{})}const a=$('#cl_ra');if(a){a.srcObject=rs;a.play().catch(()=>{})}};
pc.onicecandidate=e=>e.candidate&&addDoc(collection(db,'calls',cid,role),e.candidate.toJSON()).catch(()=>{});return pc}
const callBody=(u,type,status,incoming)=>`<div class="callc"><div class="calls">${type=='video'?`<video id="cl_rv" class="clrv" autoplay playsinline></video>`:`<audio id="cl_ra" autoplay></audio>`}${type=='video'?`<video id="cl_lv" class="cllv" autoplay playsinline muted></video>`:''}<div class="clin">${av(u,'xl')}<h2>${nameOf(u)}</h2><p id="cl_st">${status}</p></div></div><div class="clbt">${incoming?`<button class="clb ok" data-act="callyes">${I.phone||I.send}</button><button class="clb no" data-act="callno">${I.x}</button>`:`<button class="clb sm2" data-act="callmic">${I.mic}</button>${type=='video'?`<button class="clb sm2" data-act="callcam">${I.video||I.film}</button>`:''}<button class="clb no" data-act="callend">${I.x}</button>`}</div></div>`;
A.callto=async e=>{const to=e.dataset.u||S.rt?.arg,type=e.dataset.t||'voice';if(!to||CALL)return;if(!navigator.mediaDevices?.getUserMedia)return toast('Panggilan belum didukung di perangkat ini');
let st;try{st=await callMedia(type=='video')}catch{return toast('Izin mikrofon'+(type=='video'?' dan kamera':'')+' dibutuhkan')}
const u=await getUser(to),cid=doc(collection(db,'calls')).id,pc=callPC(cid,'caller',st,type=='video');CALL={cid,pc,st,type,role:'caller',un:[],peer:to};callUI(callBody(u,type,'Memanggil…',false));if(type=='video'){const lv=$('#cl_lv');if(lv){lv.srcObject=st;lv.play().catch(()=>{})}}ringStart(true);
try{const of=await pc.createOffer();await pc.setLocalDescription(of);await setDoc(doc(db,'calls',cid),{from:S.uid,to,type,status:'ringing',offer:{type:of.type,sdp:of.sdp},createdAt:serverTimestamp()});pushNotif(to,'call',type=='video'?'melakukan panggilan video':'melakukan panggilan suara','call_'+cid);
CALL.un.push(onSnapshot(doc(db,'calls',cid),s=>{const x=s.data();if(!x||!CALL||CALL.cid!=cid)return;if(x.answer&&!pc.currentRemoteDescription){pc.setRemoteDescription(x.answer).catch(()=>{});ringStop();$('#cl_st')&&($('#cl_st').textContent='Tersambung');callTimer()}if(x.status=='declined'){toast('Panggilan ditolak');callEnd(false)}if(x.status=='ended'){callEnd(false)}}));
CALL.un.push(onSnapshot(collection(db,'calls',cid,'callee'),s=>s.docChanges().forEach(c=>c.type=='added'&&pc.addIceCandidate(c.doc.data()).catch(()=>{}))));
CALL.to=setTimeout(()=>{if(CALL&&CALL.cid==cid&&!pc.currentRemoteDescription){toast('Tidak dijawab');callEnd(true)}},45000)}catch(x){toast(errMsg(x));callEnd(false)}};
function callTimer(){const t0=Date.now();CALL.tm=setInterval(()=>{const s=Math.round((Date.now()-t0)/1000),el=$('#cl_st');if(el)el.textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0')},1000)}
async function callEnd(notify){const C=CALL;if(!C)return;CALL=null;clearTimeout(C.to);clearInterval(C.tm);C.un.forEach(f=>f());try{C.pc.close()}catch{}C.st.getTracks().forEach(t=>t.stop());callClose();if(notify)await updateDoc(doc(db,'calls',C.cid),{status:'ended'}).catch(()=>{})}
A.callend=()=>callEnd(true);
A.callmic=e=>{const t=CALL?.st.getAudioTracks()[0];if(t){t.enabled=!t.enabled;e.classList.toggle('off',!t.enabled)}};
A.callcam=e=>{const t=CALL?.st.getVideoTracks()[0];if(t){t.enabled=!t.enabled;e.classList.toggle('off',!t.enabled)}};
let INC=null;
function callWatch(){if(S.cwOn||!S.uid)return;S.cwOn=1;onSnapshot(query(collection(db,'calls'),where('to','==',S.uid),where('status','==','ringing')),async s=>{for(const ch of s.docChanges()){if(ch.type!='added')continue;const x=ch.doc.data(),cid=ch.doc.id;const age=Date.now()-(x.createdAt?.toMillis?.()||Date.now());if(age>40000)continue;if(CALL||INC){updateDoc(ch.doc.ref,{status:'declined'}).catch(()=>{});continue}
const u=await getUser(x.from);INC={cid,x,u};callUI(callBody(u,x.type,x.type=='video'?'Panggilan video masuk':'Panggilan suara masuk',true));ringStart(false);INC.t=setTimeout(()=>{if(INC&&INC.cid==cid){updateDoc(doc(db,'calls',cid),{status:'ended'}).catch(()=>{});INC=null;callClose()}},40000);
onSnapshot(doc(db,'calls',cid),d=>{const y=d.data();if(INC&&INC.cid==cid&&(!y||y.status=='ended')){clearTimeout(INC.t);INC=null;callClose();toast('Panggilan tidak terjawab')}})}},()=>{})}
A.callno=async()=>{if(!INC)return;clearTimeout(INC.t);const c=INC.cid;INC=null;callClose();await updateDoc(doc(db,'calls',c),{status:'declined'}).catch(()=>{})};
A.callyes=async()=>{if(!INC)return;const {cid,x,u}=INC;clearTimeout(INC.t);INC=null;ringStop();let st;try{st=await callMedia(x.type=='video')}catch{toast('Izin mikrofon'+(x.type=='video'?' dan kamera':'')+' dibutuhkan');await updateDoc(doc(db,'calls',cid),{status:'declined'}).catch(()=>{});return callClose()}
const pc=callPC(cid,'callee',st,x.type=='video');CALL={cid,pc,st,type:x.type,role:'callee',un:[],peer:x.from};callUI(callBody(u,x.type,'Menyambungkan…',false));if(x.type=='video'){const lv=$('#cl_lv');if(lv){lv.srcObject=st;lv.play().catch(()=>{})}}
try{await pc.setRemoteDescription(x.offer);const an=await pc.createAnswer();await pc.setLocalDescription(an);await updateDoc(doc(db,'calls',cid),{answer:{type:an.type,sdp:an.sdp},status:'accepted'});$('#cl_st')&&($('#cl_st').textContent='Tersambung');callTimer();
CALL.un.push(onSnapshot(collection(db,'calls',cid,'caller'),s=>s.docChanges().forEach(c=>c.type=='added'&&pc.addIceCandidate(c.doc.data()).catch(()=>{}))));CALL.un.push(onSnapshot(doc(db,'calls',cid),s=>{const y=s.data();if(!y||y.status=='ended')callEnd(false)}))}catch(err){toast(errMsg(err));callEnd(true)}};

